@pytest.fixture(scope='module')
def catalog(tmp_path_factory):
    return load_rules(tmp_path_factory.mktemp('no-override'))


@pytest.mark.parametrize(
    'label,body,facts,policy,verdict,rows', CASES, ids=[case[0] for case in CASES]
)
def test_corpus_case(catalog, label, body, facts, policy, verdict, rows) -> None:
    result = evaluate(body, Facts.model_validate(facts), Policy(families=policy), catalog)
    got = sorted([r.rule_id, r.requiredness, r.disposition] for r in result.requirements)
    assert result.verdict == verdict
    assert got == sorted(rows)


def test_the_corpus_is_complete() -> None:
    assert len(CASES) == 988
